import React, { useState } from 'react';
import { Stage, Layer, Line, Circle, Text, Rect } from 'react-konva';

const CadConfigurator = () => {
  // --- State Management ---
  const [selectedOperation, setSelectedOperation] = useState('extrude');
  const [currentVertices, setCurrentVertices] = useState([]);
  const [isProfileClosed, setIsProfileClosed] = useState(false);
  const [savedBodies, setSavedBodies] = useState([]);

  // Operation-specific parameters
  const [sweepComponentType, setSweepComponentType] = useState('profile');
  const [revolutionAxis, setRevolutionAxis] = useState('Y');
  const [extrusionLength, setExtrusionLength] = useState(100);

  // --- Constants ---
  const CANVAS_WIDTH = 700;
  const CANVAS_HEIGHT = 500;
  const GRID_SIZE = 20;
  const MAJOR_GRID_SIZE = 100;

  // --- Handlers ---
  const snapToGrid = (value) => Math.round(value / GRID_SIZE) * GRID_SIZE;

  const handleCanvasClick = (event) => {
    if (isProfileClosed) return;
    const pointerPosition = event.target.getStage().getPointerPosition();

    // Ignore clicks in the top/left ruler margins (first 20px)
    if (pointerPosition.x < GRID_SIZE || pointerPosition.y < GRID_SIZE) return;

    const snappedX = snapToGrid(pointerPosition.x);
    const snappedY = snapToGrid(pointerPosition.y);
    setCurrentVertices([...currentVertices, snappedX, snappedY]);
  };

  const handleCanvasDoubleClick = () => {
    if (currentVertices.length >= 6) setIsProfileClosed(true);
  };

  const clearCanvas = () => {
    setCurrentVertices([]);
    setIsProfileClosed(false);
  };

  const saveCurrentBody = () => {
    const formattedVertices = [];
    for (let i = 0; i < currentVertices.length; i += 2) {
      formattedVertices.push([currentVertices[i], currentVertices[i + 1]]);
    }
    setSavedBodies([
      ...savedBodies, 
      { type: sweepComponentType, vertices: formattedVertices, isClosed: isProfileClosed }
    ]);
    clearCanvas();
  };

  const exportPayload = () => {
    const formattedVertices = [];
    for (let i = 0; i < currentVertices.length; i += 2) {
      // Subtract GRID_SIZE so the exported coordinates start at 0,0 relative to the drawing area
      formattedVertices.push([currentVertices[i] - GRID_SIZE, currentVertices[i + 1] - GRID_SIZE]);
    }

    const payload = { operationType: selectedOperation };

    if (selectedOperation === 'extrude') {
      payload.length = extrusionLength;
      payload.profile = { vertices: formattedVertices, isClosed: isProfileClosed };
    } else if (selectedOperation === 'revolve') {
      payload.axisOfRotation = revolutionAxis === 'Y' ? [0, 1, 0] : [1, 0, 0];
      payload.degrees = 360;
      payload.profile = { vertices: formattedVertices, isClosed: isProfileClosed };
    } else if (selectedOperation === 'sweep') {
      payload.crossSection = savedBodies.find(b => b.type === 'profile') || {};
      payload.sweepPath = savedBodies.find(b => b.type === 'path') || {};
    } else if (selectedOperation === 'union') {
      payload.bodies = savedBodies.map(b => ({ type: 'extrude', profile: b, length: extrusionLength }));
    }

    console.log("JSON Payload:", JSON.stringify(payload, null, 2));
  };

  // --- Render Helpers ---
  const renderGridAndAxes = () => {
    const elements = [];

    // Background filling for ruler area
    elements.push(<Rect key="ruler-x" x={0} y={0} width={CANVAS_WIDTH} height={GRID_SIZE} fill="#f1f5f9" />);
    elements.push(<Rect key="ruler-y" x={0} y={0} width={GRID_SIZE} height={CANVAS_HEIGHT} fill="#f1f5f9" />);

    // Vertical Lines and X-Axis Labels
    for (let i = 0; i <= CANVAS_WIDTH / GRID_SIZE; i++) {
      const xPos = i * GRID_SIZE;
      const isMajor = xPos % MAJOR_GRID_SIZE === 0;
      elements.push(
        <Line key={`v-line-${i}`} points={[xPos, 0, xPos, CANVAS_HEIGHT]} stroke={isMajor ? "#cbd5e1" : "#e2e8f0"} strokeWidth={1} />
      );
      if (isMajor && xPos > 0) {
        elements.push(<Text key={`text-x-${i}`} x={xPos + 2} y={2} text={`${xPos - GRID_SIZE}`} fontSize={10} fill="#64748b" />);
      }
    }

    // Horizontal Lines and Y-Axis Labels
    for (let j = 0; j <= CANVAS_HEIGHT / GRID_SIZE; j++) {
      const yPos = j * GRID_SIZE;
      const isMajor = yPos % MAJOR_GRID_SIZE === 0;
      elements.push(
        <Line key={`h-line-${j}`} points={[0, yPos, CANVAS_WIDTH, yPos]} stroke={isMajor ? "#cbd5e1" : "#e2e8f0"} strokeWidth={1} />
      );
      if (isMajor && yPos > 0) {
        elements.push(<Text key={`text-y-${j}`} x={2} y={yPos + 2} text={`${yPos - GRID_SIZE}`} fontSize={10} fill="#64748b" />);
      }
    }
    return elements;
  };

  return (
    <div className="max-w-6xl mx-auto p-6 bg-gray-100 min-h-screen font-sans">
      <header className="mb-6">
        <h1 className="text-2xl font-bold text-gray-800">UG Project: Parametric Beam Generator</h1>
        <p className="text-gray-600 text-sm">Draw cross-sections on the grid and define operations to generate 3D STEP files.</p>
      </header>

      <div className="flex flex-col md:flex-row gap-6">

        {/* Sidebar Controls */}
        <div className="w-full md:w-72 bg-white p-5 rounded-lg shadow-sm border border-gray-200 flex flex-col gap-5 h-fit">
          <h2 className="font-semibold text-gray-700 border-b pb-2">Operation Parameters</h2>

          <div className="flex flex-col gap-2">
            <label className="text-xs font-medium text-gray-500 uppercase">Operation Type</label>
            <select 
              value={selectedOperation} 
              onChange={(e) => { setSelectedOperation(e.target.value); setSavedBodies([]); clearCanvas(); }} 
              className="w-full border border-gray-300 rounded p-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500"
            >
              <option value="extrude">Extrude</option>
              <option value="revolve">Revolve</option>
              <option value="sweep">Sweep</option>
              <option value="union">Boolean Union</option>
            </select>
          </div>

          {selectedOperation === 'extrude' && (
            <div className="flex flex-col gap-2">
              <label className="text-xs font-medium text-gray-500 uppercase">Extrusion Length (mm)</label>
              <input type="number" value={extrusionLength} onChange={(e) => setExtrusionLength(Number(e.target.value))} className="w-full border border-gray-300 rounded p-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500" />
            </div>
          )}

          {selectedOperation === 'revolve' && (
            <div className="flex flex-col gap-2">
              <label className="text-xs font-medium text-gray-500 uppercase">Rotation Axis</label>
              <select value={revolutionAxis} onChange={(e) => setRevolutionAxis(e.target.value)} className="w-full border border-gray-300 rounded p-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                <option value="Y">Y-Axis (Vertical)</option>
                <option value="X">X-Axis (Horizontal)</option>
              </select>
            </div>
          )}

          {selectedOperation === 'sweep' && (
            <div className="flex flex-col gap-2">
              <label className="text-xs font-medium text-gray-500 uppercase">Active Sketch</label>
              <select value={sweepComponentType} onChange={(e) => setSweepComponentType(e.target.value)} className="w-full border border-gray-300 rounded p-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500">
                <option value="profile">Cross-Section Profile</option>
                <option value="path">Sweep Path</option>
              </select>
            </div>
          )}

          <div className="mt-4 pt-4 border-t flex flex-col gap-3">
            {(selectedOperation === 'sweep' || selectedOperation === 'union') && (
              <button onClick={saveCurrentBody} className="w-full py-2 bg-gray-100 text-gray-700 font-medium rounded hover:bg-gray-200 border border-gray-300 transition-colors">
                Save Current Sketch
              </button>
            )}
            <button onClick={clearCanvas} className="w-full py-2 bg-red-50 text-red-600 font-medium rounded hover:bg-red-100 border border-red-200 transition-colors">
              Clear Canvas
            </button>
            <button 
              onClick={exportPayload} 
              disabled={!isProfileClosed && currentVertices.length < 4}
              className="w-full py-2 bg-blue-600 text-white font-medium rounded hover:bg-blue-700 disabled:bg-blue-300 transition-colors shadow-sm"
            >
              Generate 3D Model
            </button>
          </div>
        </div>

        {/* Canvas Area */}
        <div className="flex-1 bg-white p-1 rounded-lg shadow-sm border border-gray-200 overflow-hidden flex justify-center items-center bg-[url('data:image/svg+xml;base64,PHN2ZyB3aWR0aD0iMjAiIGhlaWdodD0iMjAiIHhtbG5zPSJodHRwOi8vd3d3LnczLm9yZy8yMDAwL3N2ZyI+PGNpcmNsZSBjeD0iMSIgY3k9IjEiIHI9IjEiIGZpbGw9IiNlN2U1ZTQiLz48L3N2Zz4=')]">
          <div className="border border-gray-300 bg-white cursor-crosshair shadow-sm relative">

            <Stage width={CANVAS_WIDTH} height={CANVAS_HEIGHT} onClick={handleCanvasClick} onDblClick={handleCanvasDoubleClick}>
              <Layer>
                {renderGridAndAxes()}
              </Layer>
              <Layer>
                {/* User Drawn Geometry */}
                <Line 
                  points={currentVertices} 
                  stroke="#2563eb" 
                  strokeWidth={2.5} 
                  closed={isProfileClosed} 
                  lineJoin="round" 
                  lineCap="round"
                />

                {/* Vertex Points */}
                {currentVertices.map((point, index) => 
                  index % 2 === 0 ? (
                    <Circle 
                      key={`vertex-${index}`} 
                      x={currentVertices[index]} 
                      y={currentVertices[index + 1]} 
                      radius={4} 
                      fill="#ef4444" 
                      stroke="#ffffff"
                      strokeWidth={1}
                    />
                  ) : null
                )}
              </Layer>
            </Stage>

            {/* Helper tooltip overlay */}
            <div className="absolute top-3 right-4 bg-white/80 px-2 py-1 text-xs text-gray-500 rounded border backdrop-blur-sm pointer-events-none">
              Double-click to close shape
            </div>
          </div>
        </div>

      </div>
    </div>
  );
};

export default CadConfigurator;
